"""Wound and injury catalogue: (category, tier, name, region, description-template). Clinical, detached wording."""
def S(x): return [i.strip() for i in x.split(';') if i.strip()]
LOC = {
 'side': ['left', 'right'],
 'arm': S("the left forearm; the right forearm; the left upper arm; the right upper arm; the left elbow; the right elbow; the left wrist; the right wrist"),
 'hand': S("the left palm; the right palm; the left index finger; the right index finger; the left thumb; the right thumb; the back of the left hand; the back of the right hand; the left ring finger; the right middle finger"),
 'leg': S("the left shin; the right shin; the left thigh; the right thigh; the left knee; the right knee; the left calf; the right calf; the left ankle; the right ankle"),
 'foot': S("the sole of the left foot; the sole of the right foot; the left heel; the right heel; the left big toe; the right big toe; the top of the left foot; the top of the right foot"),
 'torso': S("the left side of the chest; the right side of the chest; the upper abdomen; the lower abdomen; the upper back; the lower back; the left flank; the right flank; the left shoulder; the right shoulder"),
 'head': S("the left temple; the right temple; the forehead; the crown of the scalp; the back of the scalp; the left cheek; the right cheek; the chin; the left eyebrow; the right eyebrow; the bridge of the nose; the lower lip; the left ear; the right ear"),
 'face': S("the forehead; the left cheek; the right cheek; the chin; the nose; the upper lip; the area around the left eye; the area around the right eye; the jawline"),
 'neck': S("the left side of the neck; the right side of the neck; the back of the neck"),
 'skin': S("the forearms; the face and neck; the chest and trunk; the back; the legs; the hands; the whole body surface; the upper arms and shoulders; the abdomen; the thighs"),
 'eye': S("the left eye; the right eye"),
 'mouth': S("the front teeth; the lower lip and teeth; the tongue; the gums"),
 'bone_arm': S("the left forearm; the right forearm; the left upper arm; the right upper arm; the left wrist; the right wrist; the left collarbone; the right collarbone; the left elbow; the right elbow"),
 'bone_leg': S("the left shin; the right shin; the left thigh; the right thigh; the left ankle; the right ankle; the left kneecap; the right kneecap; the left hip; the right hip"),
}
STAGE = {
 'gen': S("fresh, with active bleeding; fresh, with the bleeding controlled; one day old, with a dry scab forming; three days old, with surrounding bruising; one week old, partly healed; two weeks old, with pink new skin; healed, leaving a faint pale mark; healed, leaving a raised scar; healed, leaving a depressed scar; infected, with redness and swelling; being treated, with a clean dressing in place; stitched and dressed; cleaned and awaiting treatment; at the stage of removing the stitches"),
 'fracture': S("acute, with swelling and bruising over the site; held in a splint; set in a cast that is clean and white; set in a cast covered with signatures; held in a sling; after cast removal, with pale skin and wasted muscle; healed, with a palpable bony lump at the site; in traction with weights and pulleys; fixed with a surgical plate and screws, with a healed incision scar; fixed with an external frame of rods and pins; seen on the day of injury with an obvious deformity"),
 'burn': S("acute, with redness and heat; with intact fluid-filled blisters; with ruptured, weeping blisters; dressed with silver-impregnated gauze; covered with a skin graft; healing, with pink new skin; healed, leaving a contracted shiny scar; healed, leaving a patch of discoloured skin; wrapped in loose cling film in the first hour; cooled under running water"),
 'contagion': S("at the first appearance, with a few scattered lesions; at its peak, with the full rash across the area; with lesions crusting over; resolving, with fading marks; spreading to neighbouring skin; in the person wearing a face mask and gloves as an isolation measure; under treatment, with a medicated dressing; scratched open and weeping"),
 'bite': S("fresh, with active bleeding; cleaned and dressed; with swelling and bruising around the marks; infected, with redness and pus; one week old, partly healed; healed, leaving scattered small scars; marked with an ink outline by a clinician to track the spread of redness"),
}
# (category, tier, name, region, template, stage-key)
C = []
def add(cat, tier, name, region, tpl, st='gen'): C.append((cat, tier, name, region, tpl, st))
# --- minor trauma
for n,r,t in [
 ('a paper cut','hand',"a thin superficial linear cut about 1 cm long with a fine red edge and minimal bleeding, on {l}"),
 ('a scraped knee','leg',"an abrasion about 4 cm wide with raw pink skin and fine surface bleeding, on {l}"),
 ('a splinter','hand',"a small dark linear foreign body under the skin with a rim of redness, on {l}"),
 ('a blister','foot',"a fluid-filled blister about 2 cm wide with a taut translucent roof, on {l}"),
 ('a minor kitchen cut','hand',"a clean 2 cm incision with gaping edges and bright red blood, on {l}"),
 ('a small bruise','leg',"a blue-purple bruise about 5 cm wide with a yellowing margin, on {l}"),
 ('a nosebleed','face',"dried blood below the nostril and on the upper lip, with a swollen nasal lining, near {l}"),
 ('a jammed finger','hand',"a swollen, tender finger joint with limited bending and no deformity, on {l}"),
 ('a grazed elbow','arm',"a shallow graze about 5 cm long with weeping serum, on {l}"),
 ('a rope burn','arm',"a linear red friction burn about 8 cm long with peeling skin, on {l}"),
 ('a cat scratch','arm',"three parallel superficial scratches about 4 cm long with fine red edges, on {l}"),
 ('a thorn puncture','hand',"a pinpoint puncture with a rim of redness and a small bead of blood, on {l}"),
 ('a fishhook injury','hand',"a hook embedded to the barb with a small ring of swelling and a drop of blood, in {l}"),
 ('a staple puncture','hand',"a tiny round puncture with a drop of blood and a ring of redness, in {l}"),
 ('a torn fingernail','hand',"a partly detached nail with a bleeding nail bed and dried blood, on {l}"),
 ('a subungual haematoma','hand',"a dark purple-black collection of blood under the nail covering half the nail, on {l}"),
 ('a bitten tongue','mouth',"a swollen, bruised tongue with a small split edge and dried blood, at {l}"),
 ('a mild whiplash','neck',"stiffness and mild swelling of the muscles with a limited range of turning, at {l}"),
 ('a muscle strain','leg',"a tender swollen muscle belly with a faint bruise below it, at {l}"),
 ('a rug burn','arm',"a broad shiny pink friction abrasion with a fine surface weep, on {l}"),
 ]: add('minor','minor',n,r,t)
# --- bites and stings
for n,r,t,tier in [
 ('a bee sting','arm',"a raised red papule about 2 cm wide with a central punctum and surrounding swelling, on {l}",'minor'),
 ('a wasp sting','arm',"a hot, swollen, red area about 4 cm wide with a central punctum, on {l}",'minor'),
 ('an insect bite','arm',"a raised red wheal about 1.5 cm wide with a small central punctum, on {l}",'minor'),
 ('a cluster of mosquito bites','arm',"a group of small raised red wheals, each 0.5 to 1 cm, scratched in places, on {l}",'minor'),
 ('bedbug bites','arm',"a line of three red itchy papules with small central marks, on {l}",'minor'),
 ('flea bites','leg',"clusters of small red papules with a darker centre around {l}",'minor'),
 ('a tick bite with a bullseye rash','leg',"a central bite mark with an expanding ring of redness and a clear zone, about 8 cm across, on {l}",'moderate'),
 ('a spider bite','arm',"two small puncture marks with a red halo and central blanching, on {l}",'moderate'),
 ('a necrotic spider bite','leg',"a central dark ulcer with a blue-grey margin and a wide red halo, on {l}",'severe'),
 ('a jellyfish sting','leg',"raised red-brown linear welts in a whip pattern about 20 cm long, on {l}",'moderate'),
 ('a stingray puncture','foot',"a jagged puncture with ragged edges, swelling and a blue-grey margin, on {l}",'severe'),
 ('a sea urchin spine injury','foot',"multiple small black puncture points with surrounding redness and swelling, on {l}",'moderate'),
 ('a scorpion sting','arm',"a small puncture with local swelling and a red area about 3 cm wide, on {l}",'moderate'),
 ('a snakebite','leg',"two puncture marks about 1 cm apart with swelling spreading up the limb, blistering and purple bruising, on {l}",'severe'),
 ('a cat bite','hand',"a small deep puncture with swelling and redness spreading outwards, on {l}",'moderate'),
 ('a dog bite','leg',"a cluster of puncture wounds and a ragged tear about 6 cm long with surrounding bruising, on {l}",'moderate'),
 ('a human bite','arm',"a curved double row of tooth marks with bruising, on {l}",'moderate'),
 ('a horse kick','leg',"a rounded bruise about 15 cm wide showing the shape of a hoof, with swelling, on {l}",'moderate'),
 ('a large dog attack','arm',"multiple deep tears with loose flaps of skin, exposed muscle and heavy bleeding, on {l}",'severe'),
 ('a bear mauling','torso',"parallel deep claw lacerations 15 to 25 cm long with ragged edges and exposed muscle, across {l}",'critical'),
 ('a shark bite','leg',"a curved crescent of deep tooth lacerations with missing tissue and heavy bleeding, on {l}",'critical'),
 ('a crocodile bite','leg',"paired crush wounds with deep punctures, torn muscle and bone injury, on {l}",'critical'),
 ('an allergic sting reaction','face',"marked swelling of the lips and eyelids with raised red hives spreading across {l}",'severe'),
 ]: add('bite_sting',tier,n,r,t,'bite')
# --- punctures, stabs, impalements, projectiles
for n,r,t,tier in [
 ('a nail puncture','foot',"a small round puncture wound with a dark rim and surrounding swelling, on {l}",'moderate'),
 ('a stab wound','torso',"a narrow clean-edged incision about 3 cm long with dark bleeding and swelling around the edges, at {l}",'severe'),
 ('a deep stab wound with a retained blade','torso',"a blade seated in the tissue with blood around it and no attempt to remove it, at {l}",'critical'),
 ('an impalement injury','torso',"a metal rod passing through the tissue, with bleeding around the entry and exit points, at {l}",'critical'),
 ('a glass shard injury','arm',"a long jagged cut with a piece of glass still embedded and bleeding around it, on {l}",'moderate'),
 ('a screwdriver puncture','hand',"a round deep puncture about 6 mm wide with bleeding, on {l}",'moderate'),
 ('an arrow wound','torso',"a shaft embedded in the tissue with a clean entry wound and bleeding around it, at {l}",'severe'),
 ('a gunshot entry wound','torso',"a round entry wound about 1 cm wide with a dark rim of abrasion and little bleeding, at {l}",'critical'),
 ('a gunshot exit wound','torso',"a ragged irregular wound about 3 cm wide with torn edges and heavy bleeding, at {l}",'critical'),
 ('a shotgun pellet scatter','leg',"dozens of small round punctures in a spray pattern, each with a dark rim and little bleeding, on {l}",'severe'),
 ('shrapnel injuries','torso',"multiple irregular puncture wounds with embedded fragments and surrounding bruising, across {l}",'severe'),
 ('a puncture of the thigh by a branch','leg',"a deep ragged puncture with bark fragments in the wound and bleeding, in {l}",'severe'),
 ('a tattoo-needle accident puncture','arm',"a cluster of tiny ink-stained punctures with mild swelling, on {l}",'minor'),
 ('a pierced cheek','face',"a through-and-through puncture of the cheek with swelling and bleeding on both sides, at {l}",'severe'),
 ('a penetrating chest wound','torso',"a wound with an occlusive dressing, bubbling at the edges and blood-stained, at {l}",'critical'),
 ]: add('puncture',tier,n,r,t)
# --- lacerations, avulsions, cuts
for n,r,t,tier in [
 ('a laceration with sutures','arm',"a 5 cm linear laceration with the edges brought together by six black nylon sutures and mild surrounding bruising, on {l}",'moderate'),
 ('a laceration closed with staples','torso',"a 7 cm wound closed by a row of metal staples with a thin crust of dried blood, on {l}",'moderate'),
 ('a laceration closed with glue','face',"a 3 cm wound with the edges sealed by a thin line of clear surgical glue, on {l}",'minor'),
 ('a butterfly-closed cut','face',"a 2 cm cut with the edges drawn together by two paper strips, on {l}",'minor'),
 ('a deep gash','leg',"a 7 cm open laceration with visible subcutaneous fat and brisk bleeding, on {l}",'moderate'),
 ('a deep laceration with exposed tendon','hand',"an open wound about 5 cm long showing a white tendon at the base with brisk bleeding, on {l}",'severe'),
 ('a facial laceration','face',"a 10 cm laceration with ragged edges, deep tissue exposed and heavy bleeding, across {l}",'severe'),
 ('a scalp laceration','head',"a 6 cm scalp laceration with heavy bleeding, matted hair and a visible swelling beneath, at {l}",'severe'),
 ('a degloving injury','hand',"a flap of skin peeled back from the underlying tissue, exposing red muscle and white bone, on {l}",'severe'),
 ('a large avulsion','leg',"a wide area of missing skin and tissue, with exposed muscle and weeping fluid, on {l}",'severe'),
 ('a skin flap tear','arm',"a triangular flap of skin torn back, with a pale underside and oozing blood, on {l}",'moderate'),
 ('a neck laceration with pressure applied','neck',"a deep wound controlled by a pressure dressing soaked in blood, at {l}",'severe'),
 ('a scalping injury','head',"a large section of scalp torn back with exposed skull and heavy bleeding, at {l}",'critical'),
 ('an ear tear','head',"a split through the ear with torn cartilage and bleeding, at {l}",'moderate'),
 ('a lip laceration through the vermilion border','face',"a full-thickness split of the lip that crosses the lip line, with swelling and dried blood, at {l}",'moderate'),
 ('a slashed forearm','arm',"a long clean-edged cut about 12 cm long with gaping edges and venous bleeding, on {l}",'severe'),
 ('a road rash','leg',"a large abrasion about 20 cm long with embedded grit and weeping serum, on {l}",'moderate'),
 ('a deep abrasion with embedded gravel','arm',"a raw red area with dark gravel fragments pressed into the surface and oozing serum, on {l}",'moderate'),
 ('a sutured surgical incision','torso',"a straight 12 cm incision closed by fine stitches with a pink line and mild bruising, on {l}",'moderate'),
 ('a stapled surgical incision with a drain','torso',"a long incision closed by staples with a clear drain tube exiting nearby, on {l}",'severe'),
 ('a Y-shaped autopsy-style scar','torso',"a long pale healed scar shaped like a Y across the chest and abdomen, on {l}",'moderate'),
 ('keloid scars','torso',"raised thick rope-like pink scars along old incisions, on {l}",'minor'),
 ('stretch-mark scars after rapid growth','torso',"parallel silvery lines running across the skin, on {l}",'minor'),
 ]: add('laceration',tier,n,r,t)
# --- bruising, sprains, dislocations
for n,r,t,tier in [
 ('a black eye','face',"periorbital swelling with a purple-blue bruise that has partly closed the eyelid, around {l}",'moderate'),
 ('a severe bruise','leg',"a large dark blue-black bruise about 20 cm wide with a hard swelling, on {l}",'moderate'),
 ('a haematoma','leg',"a tense, dark, firm swelling about 8 cm wide, on {l}",'moderate'),
 ('a sprained ankle','foot',"a swollen ankle with diffuse bruising along the outer side, reduced movement and a mild limp, near {l}",'moderate'),
 ('a dislocated shoulder','torso',"a flattened shoulder contour with the arm held away from the body, at {l}",'moderate'),
 ('a dislocated finger','hand',"a finger bent at a sharp angle at the joint with swelling, on {l}",'moderate'),
 ('a dislocated kneecap','leg',"a visible bump at the side of the knee with the leg held bent, at {l}",'moderate'),
 ('a dislocated elbow','arm',"a swollen, deformed elbow held bent, at {l}",'severe'),
 ('a dislocated hip','leg',"a leg that is shortened and rotated inwards, with severe pain on movement, at {l}",'severe'),
 ('a torn ligament','leg',"a swollen, unstable joint with deep bruising and a reduced range of movement, at {l}",'moderate'),
 ('a ruptured Achilles tendon','foot',"a visible gap above the heel with swelling, bruising and loss of the foot's push, at {l}",'severe'),
 ('whiplash with a soft collar','neck',"a soft foam collar fitted with stiffness and mild bruising, at {l}",'moderate'),
 ('a concussion sign','head',"a raised bruised swelling with dilated pupils and a vacant stare, at {l}",'moderate'),
 ('a bruised rib cage','torso',"large dark bruising with tenderness and pain on deep breathing, at {l}",'moderate'),
 ('a compartment syndrome swelling','leg',"a tight, shiny, swollen limb with pale skin and severe pain, at {l}",'critical'),
 ]: add('bruise_sprain',tier,n,r,t)
# --- fractures
for n,r,t,tier in [
 ('a simple closed fracture','bone_arm',"a closed fracture with swelling, bruising and tenderness over the bone and no break in the skin, at {l}",'moderate'),
 ('a greenstick fracture','bone_arm',"a bowed bone with a partial break on one side, with swelling and tenderness, at {l}",'moderate'),
 ('a comminuted fracture','bone_leg',"a bone broken into several fragments with marked swelling and deformity, at {l}",'severe'),
 ('a spiral fracture','bone_leg',"a twisting break with a swollen limb held in an abnormal position, at {l}",'severe'),
 ('an oblique fracture','bone_leg',"a diagonal break with swelling, bruising and a shortened limb, at {l}",'severe'),
 ('a transverse fracture','bone_arm',"a break straight across the bone with a visible angle and swelling, at {l}",'moderate'),
 ('a compound fracture','bone_leg',"a fracture of the long bone with a bone end exposed through a wound about 4 cm long, with surrounding swelling and bleeding, at {l}",'severe'),
 ('a stress fracture','bone_leg',"a point-tender swelling on the bone without deformity, at {l}",'minor'),
 ('a Colles fracture of the wrist','bone_arm',"a dinner-fork deformity of the wrist with swelling and bruising, at {l}",'moderate'),
 ('a broken collarbone','bone_arm',"a visible bump on the collarbone with the shoulder drooping forward and bruising, at {l}",'moderate'),
 ('a broken nose','face',"a nasal deformity with swelling, bruising across the bridge and dried blood in the nostrils, at {l}",'moderate'),
 ('a broken jaw','face',"swelling of the jaw with bruising under the chin, a misaligned bite and drooling, at {l}",'severe'),
 ('an orbital fracture','face',"swelling and bruising around the eye with a sunken eye and double vision, at {l}",'severe'),
 ('a cheekbone fracture','face',"a flattened cheek with numbness and swelling and a bloodshot eye, at {l}",'severe'),
 ('a skull fracture sign','head',"a depressed area of the skull with scalp bruising, clear fluid at the ear and a dark swelling, at {l}",'critical'),
 ('a broken rib','torso',"localised bruising and tenderness with pain on deep breathing and guarded movement, at {l}",'moderate'),
 ('a flail chest','torso',"a segment of the chest wall that moves inward on breathing in, with bruising, at {l}",'critical'),
 ('a broken vertebra','torso',"localised swelling and tenderness of the spine with a stiff, guarded posture, at {l}",'critical'),
 ('a pelvic fracture','torso',"bruising over the hips and groin with a shortened, rotated leg, at {l}",'critical'),
 ('a hip fracture','bone_leg',"a leg that is shortened and turned out with bruising and severe pain, at {l}",'severe'),
 ('a boxer\'s fracture','hand',"a depressed knuckle with swelling over the back of the hand, on {l}",'moderate'),
 ('a scaphoid fracture','bone_arm',"swelling at the base of the thumb with tenderness in the anatomical snuffbox, at {l}",'moderate'),
 ('a broken toe','foot',"a swollen, purple toe angled to one side, on {l}",'minor'),
 ('a broken finger','hand',"a swollen finger with an angled deformity and a purple bruise at the joint, on {l}",'moderate'),
 ('a broken arm in a sling','bone_arm',"a swollen forearm held across the chest with obvious angulation, at {l}",'moderate'),
 ('a broken leg with a visible bend','bone_leg',"a limb with an obvious bend between the joints and heavy swelling, at {l}",'severe'),
 ('a crush injury with bone fragments','bone_leg',"a limb with open wounds, bone fragments visible through the skin and extensive swelling, at {l}",'critical'),
 ('a fractured kneecap','bone_leg',"a swollen, bruised knee with a visible gap above the kneecap, at {l}",'moderate'),
 ('a dental fracture','mouth',"a chipped and cracked tooth with sharp edges and bleeding gums, at {l}",'minor'),
 ('a knocked-out tooth','mouth',"a missing tooth with an empty bleeding socket and swollen gum, at {l}",'moderate'),
 ]: add('fracture',tier,n,r,t,'fracture')
# --- burns and environmental
for n,r,t,tier in [
 ('a minor burn','hand',"a first-degree burn with redness, mild swelling and no blisters, about 3 cm wide, on {l}",'minor'),
 ('a sunburn patch','arm',"a red, hot, tight area of sunburn about 15 cm wide, on {l}",'minor'),
 ('a second-degree burn','arm',"a burn about 6 cm wide with intact blisters, a moist red base and marked pain on touch, on {l}",'moderate'),
 ('a scald from boiling water','arm',"a patchy red and blistered area with a splash margin that runs downward, about 12 cm long, on {l}",'moderate'),
 ('a hot oil burn','hand',"a red, glossy blistered area with a ragged splash pattern, on {l}",'moderate'),
 ('a contact burn from an iron','arm',"a sharply outlined red burn the shape of the iron's face with blistering at the centre, on {l}",'moderate'),
 ('a cigarette-sized burn','arm',"a round deep burn about 8 mm wide with a pale base and a ring of redness, on {l}",'minor'),
 ('a chemical burn','arm',"a pale, waxy, eroded area with a sharp border and redness around it, about 8 cm wide, on {l}",'severe'),
 ('an acid burn','hand',"a grey-white, thickened, eroded patch with a sharp border and weeping edges, on {l}",'severe'),
 ('a third-degree burn','arm',"a burn area about 12 cm wide with leathery white and charred skin and no sensation in the centre, on {l}",'severe'),
 ('a fourth-degree burn','leg',"charred tissue extending to the muscle and bone, with exposed tendon and little bleeding, on {l}",'critical'),
 ('an electrical burn','hand',"a small charred entry mark with a pale crater and an exit burn on the opposite side, on {l}",'severe'),
 ('lightning strike marks','torso',"fern-like branching red patterns across the skin, with scorched clothing nearby, across {l}",'severe'),
 ('frostnip','face',"pale, waxy, numb skin that turns red and tingling on warming, on {l}",'minor'),
 ('frostbite','hand',"white, hard, blistered fingertips that turn blue-black as the tissue dies, on {l}",'severe'),
 ('frostbitten toes','foot',"swollen, blistered, purple-black toes with a clear demarcation, on {l}",'severe'),
 ('a flash burn','face',"red, tight skin with singed eyebrows and eyelashes, across {l}",'moderate'),
 ('a steam burn','face',"diffuse redness and blistering with swelling of the eyelids, across {l}",'severe'),
 ('a large burn covering most of the torso','torso',"large areas of charred and blistered skin with fluid loss and dressings applied, across {l}",'critical'),
 ('a burn graft donor site','leg',"a raw, weeping rectangle of shaved skin about 10 cm long under a dressing, on {l}",'moderate'),
 ('a skin graft','arm',"a mesh of pink skin with a diamond pattern, stitched at the edges, on {l}",'moderate'),
 ('a radiation burn','skin',"a sharply bordered area of dry, red, peeling skin that darkens as it heals, on {l}",'severe'),
 ('heat rash','skin',"fine red pinpoint bumps over sweaty skin, on {l}",'minor'),
 ('heat exhaustion signs','skin',"flushed, sweaty skin with a pale clammy look, on {l}",'moderate'),
 ('hypothermia signs','skin',"pale, cold, mottled skin with blue lips and shivering, on {l}",'severe'),
 ]: add('burn',tier,n,r,t,'burn')
# --- infections and contagion
for n,r,t,tier in [
 ('cellulitis','leg',"a spreading area of hot, red, swollen skin with ill-defined borders and tenderness, on {l}",'moderate'),
 ('an abscess','torso',"a firm, red, warm swelling about 4 cm wide with a central pointing head, on {l}",'moderate'),
 ('a boil','neck',"a red, painful lump about 2 cm wide with a yellow centre, on {l}",'minor'),
 ('a carbuncle','torso',"a cluster of connected boils forming a broad red swelling with several draining points, on {l}",'moderate'),
 ('impetigo','face',"honey-coloured crusted sores around the mouth and nose, at {l}",'minor'),
 ('chickenpox','skin',"clusters of small itchy red spots and fluid-filled blisters at different stages, with some crusted, on {l}",'moderate'),
 ('shingles','torso',"a band of red, grouped blisters along one side of the body that does not cross the midline, on {l}",'moderate'),
 ('measles','skin',"a blotchy red-brown rash that begins on the face and spreads downwards, with red eyes, over {l}",'moderate'),
 ('scarlet fever','skin',"a fine sandpaper-like red rash with flushed cheeks and a pale ring around the mouth, over {l}",'moderate'),
 ('hand, foot and mouth disease','hand',"small oval blisters with red rims on the palms, soles and in the mouth, on {l}",'moderate'),
 ('mumps','face',"a firm swelling in front of and below the ear, giving a rounded cheek, at {l}",'moderate'),
 ('rubella','skin',"a pink, fine-spotted rash starting on the face, with swollen glands behind the ears, over {l}",'moderate'),
 ('monkeypox-style lesions','skin',"firm, deep-seated round lesions with a central dimple, some crusting, over {l}",'severe'),
 ('smallpox-style pustules','skin',"uniform, deep, firm pustules at the same stage of development across {l}",'critical'),
 ('scabies','hand',"intense itchy red papules and fine linear burrows, with scratch marks, between the fingers of {l}",'minor'),
 ('ringworm','skin',"circular scaly red patches with clear centres and raised edges, on {l}",'minor'),
 ('athlete\'s foot','foot',"peeling, red, cracked skin between the toes of {l}",'minor'),
 ('cold sores','face',"a cluster of small blisters on a red base that crust over, on {l}",'minor'),
 ('conjunctivitis','eye',"a red, swollen eyelid with watery discharge and crusting on the lashes, in {l}",'minor'),
 ('a stye','eye',"a red, tender lump on the eyelid margin with a yellow head, near {l}",'minor'),
 ('head lice','head',"small white nits attached to hairs near the scalp with red scratch marks, on {l}",'minor'),
 ('hives','skin',"raised, red, itchy wheals of varying sizes that come and go, over {l}",'minor'),
 ('eczema flare','skin',"red, dry, cracked patches with scratch marks and weeping areas, on {l}",'minor'),
 ('psoriasis plaques','skin',"well-defined red plaques with silvery scale, on {l}",'minor'),
 ('acne with pustules','face',"red inflamed spots and white-headed pustules, with some old marks, on {l}",'minor'),
 ('rosacea','face',"persistent redness with small visible vessels and bumps across {l}",'minor'),
 ('warts','hand',"rough, round, raised skin-coloured bumps with tiny black dots, on {l}",'minor'),
 ('a cold-weather chilblain','foot',"swollen, red-purple, itchy patches on {l}",'minor'),
 ('an infected piercing','head',"a red, swollen, tender area with yellow discharge around the jewellery site, at {l}",'minor'),
 ('an infected wound with red streaking','arm',"a hot, red wound with a red line tracking up the limb towards the armpit, on {l}",'severe'),
 ('a pressure sore','torso',"a shallow red crater over a bony area with a pale rim, at {l}",'moderate'),
 ('a necrotising infection','leg',"dusky purple skin with blistering, grey tissue loss and swelling spreading fast, on {l}",'critical'),
 ('gangrene','foot',"black, dry, shrunken toes with a red line of demarcation, on {l}",'critical'),
 ('sepsis mottling','leg',"a lace-like purple-blue mottling of the skin with pale cool extremities, on {l}",'critical'),
 ('jaundice','skin',"yellowing of the skin and the whites of the eyes, over {l}",'moderate'),
 ('cyanosis','skin',"a blue-grey tinge to the lips, nail beds and skin of {l}",'severe'),
 ('a leprosy-style patch','skin',"a pale, numb, well-defined skin patch with lost hair, on {l}",'moderate'),
 ('bubonic-style buboes','torso',"hard, tender, grossly swollen lymph nodes in the armpit or groin, about 5 cm wide, at {l}",'severe'),
 ('measles-style spots inside the mouth','mouth',"small white spots on a red base on the inner cheek, at {l}",'minor'),
 ('a mask-wearing person in isolation','face',"a surgical mask and gloves worn as a precaution against a contagious illness, covering {l}",'minor'),
 ]: add('contagion',tier,n,r,t,'contagion')
# --- eye, ear, mouth, head trauma
for n,r,t,tier in [
 ('a corneal abrasion','eye',"a red, tearing eye held shut, with a fine scratch visible under dye, in {l}",'minor'),
 ('a subconjunctival haemorrhage','eye',"a bright red patch of blood across the white of the eye, in {l}",'minor'),
 ('a chemical eye splash','eye',"a red, swollen, tearing eye held open under a stream of water, in {l}",'moderate'),
 ('a foreign body in the eye','eye',"a visible speck on the surface of a red, watering eye, in {l}",'minor'),
 ('a ruptured eyeball','eye',"a distorted, collapsed eye with a dark pupil and bleeding, in {l}",'critical'),
 ('an eye covered by a protective shield','eye',"a rigid shield taped over the eye with dried tears on the cheek, over {l}",'moderate'),
 ('a perforated eardrum','head',"blood-stained discharge from the ear canal, at {l}",'moderate'),
 ('a cauliflower ear','head',"a thickened, lumpy, hardened ear from repeated trauma, at {l}",'minor'),
 ('a split eyebrow','face',"a 2 cm split in the eyebrow with bleeding and swelling, over {l}",'moderate'),
 ('a hematoma on the forehead (goose egg)','head',"a firm rounded swelling about 5 cm wide with surrounding bruising, at {l}",'minor'),
 ('a lost eye with a patch','eye',"a sunken closed eyelid with a healed scar and a fabric patch held by a strap, over {l}",'moderate'),
 ('a traumatic brain injury sign','head',"bruising behind the ears and around the eyes, clear fluid from the nose, and unequal pupils, at {l}",'critical'),
 ('a severe head trauma','head',"a large scalp wound with deformity of the skull underneath, extensive blood and a dressing applied, at {l}",'critical'),
 ('a jaw wired shut','mouth',"wires and elastic bands joining the upper and lower teeth, with swelling around {l}",'moderate'),
 ('a split tongue','mouth',"a deep split in the tongue with swelling and dried blood, at {l}",'moderate'),
 ]: add('head_face',tier,n,r,t)
