 ('a traumatic above-elbow amputation','side',"the {l} arm absent above the elbow, with a pressure-dressed stump and a tourniquet at the shoulder",'critical'),
 ('a traumatic leg amputation','side',"the {l} leg absent below the knee, with a pressure-dressed stump and a tourniquet above",'critical'),
 ('a traumatic above-knee amputation','side',"the {l} leg absent above the knee, with a pressure-dressed stump and a tourniquet at the thigh",'critical'),
